/// A `.filename.mia-tmp<pid>` sibling used for atomic replacement.
fn temp_sibling(path: &Path) -> PathBuf {
    let file_name = path
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| "file".to_string());
    let tmp_name = format!(".{file_name}.mia-tmp{}", std::process::id());
    match path.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent.join(tmp_name),
        _ => PathBuf::from(tmp_name),
    }
}
#[cfg(test)]
mod tests {
    use super::*;

    fn ctx(handle: &crate::agent_loop::AgentHandle) -> ToolContext<'_> {
        ToolContext {
            handle,
            session_id: "test",
        }
    }

    fn temp_path(name: &str) -> std::path::PathBuf {
        std::env::temp_dir().join(format!("mia-test-{}-{name}", std::process::id()))
    }

    #[tokio::test]
    async fn unique_edit_applies() {
        let (_rx, handle) = crate::agent_loop::AgentHandle::new();
        let path = temp_path("edit1.txt");
        fs::write(&path, "fn main() {\n    println!(\"hi\");\n}\n").unwrap();

        let (status, payload) = FSEditFile
            .execute(
                &ctx(&handle),
                json!({
                    "path": path.to_string_lossy(),
                    "edits": [{ "old_text": "println!(\"hi\")", "new_text": "println!(\"bye\")" }]
                }),
            )
            .await;
        assert_eq!(status, ToolStatus::Success);
        assert_eq!(payload["edits_applied"], 1);
        assert!(fs::read_to_string(&path).unwrap().contains("println!(\"bye\")"));
        fs::remove_file(&path).ok();
    }

    #[tokio::test]
    async fn ambiguous_edit_fails_whole_batch_without_changes() {
        let (_rx, handle) = crate::agent_loop::AgentHandle::new();
        let path = temp_path("edit2.txt");
        let original = "aaa\nbbb\nccc\n";
        fs::write(&path, original).unwrap();

        let (status, payload) = FSEditFile
            .execute(
                &ctx(&handle),
                json!({
                    "path": path.to_string_lossy(),
                    "edits": [
                        { "old_text": "a", "new_text": "z" },                   // matches 3x
                        { "old_text": "b", "new_text": "x" }                    // never reached
                    ]
                }),
            )
            .await;
        assert!(matches!(status, ToolStatus::Error(_)));
        let msg = payload["message"].as_str().unwrap();
        assert!(msg.contains("matched 3 times"), "unexpected message: {msg}");
        // No partial writes: file unchanged.
        assert_eq!(fs::read_to_string(&path).unwrap(), original);
        fs::remove_file(&path).ok();
    }
}
